tool_calls:
cd /config; awk '
function trim(s){gsub(/^[ \t\r]+|[ \t\r]+$/,"",s);return s}
{ line=trim($0) }
line=="" || line ~ /^[;#]/ {next}
line ~ /^\[.*\]$/ { sec=line; if(!(sec in seen)){seen[sec]=1;so[++ns]=sec}; next }
{ i=index(line,"="); if(i==0)next; k=trim(substr(line,1,i-1)); v=trim(substr(line,i+1))
  id=sec SUBSEP k
  if(!(id in val)){ko[sec,++nk[sec]]=k}
  val[id]=v }
END{ for(s=1;s<=ns;s++){ sc=so[s]; if(s>1)print ""; print sc
  for(j=1;j<=nk[sc];j++){k=ko[sc,j]; print k "=" val[sc SUBSEP k]} } }
' defaults.ini custom.ini > merged.ini; cat merged.ini

